#ifdef CONFIG_MCUMGR_GRP_OS_MPSTAT
#include <zephyr/sys/sys_heap.h>

static int os_mgmt_mpstat_fixed(struct smp_streamer *ctxt)
{
	zcbor_state_t *zse = ctxt->writer->zs;
	struct sys_heap **ha;
	size_t i;
	size_t len;
	bool ok = true;

	len = sys_heap_array_get(&ha);

	for (i = 0; i < len; i++) {
		struct sys_memory_stats stats;
		int rc;
		char heap_name[4];
		uint8_t heap_name_len;

		rc = sys_heap_runtime_stats_get(ha[i], &stats);
		if (rc != 0) {
			continue;
		}

		heap_name_len = u8_to_dec(heap_name, sizeof(heap_name), (uint8_t)i);

		ok = zcbor_tstr_encode_ptr(zse, heap_name, heap_name_len) &&
		     zcbor_map_start_encode(zse, 4) &&
#ifndef CONFIG_MCUMGR_GRP_OS_MPSTAT_ONLY_SUPPORTED_STATS
		     zcbor_tstr_put_lit(zse, "blksiz") &&
		     zcbor_uint32_put(zse, 1) &&
#endif
		     zcbor_tstr_put_lit(zse, "nblks") &&
		     zcbor_uint32_put(zse,
				      (uint32_t)(stats.allocated_bytes + stats.free_bytes)) &&
		     zcbor_tstr_put_lit(zse, "nfree") &&
		     zcbor_uint32_put(zse, (uint32_t)stats.free_bytes) &&
		     zcbor_tstr_put_lit(zse, "min") &&
		     zcbor_uint32_put(zse,
				      (uint32_t)((stats.allocated_bytes + stats.free_bytes) -
						 stats.max_allocated_bytes)) &&
		     zcbor_map_end_encode(zse, 4);

		if (!ok) {
			break;
		}
	}

	return ok ? MGMT_ERR_EOK : MGMT_ERR_EMSGSIZE;
}
#endif

static void os_mgmt_register_group(void)
{
#ifdef CONFIG_MCUMGR_GRP_OS_MPSTAT
	static struct mgmt_handler
		os_mgmt_group_handlers_fixed[MAX(ARRAY_SIZE(os_mgmt_group_handlers),
						 OS_MGMT_ID_MPSTAT + 1)];

	memcpy(os_mgmt_group_handlers_fixed, os_mgmt_group_handlers,
	       sizeof(os_mgmt_group_handlers));
	os_mgmt_group_handlers_fixed[OS_MGMT_ID_MPSTAT].mh_read = os_mgmt_mpstat_fixed;
	os_mgmt_group_handlers_fixed[OS_MGMT_ID_MPSTAT].mh_write = NULL;
	os_mgmt_group.mg_handlers = os_mgmt_group_handlers_fixed;
	os_mgmt_group.mg_handlers_count = ARRAY_SIZE(os_mgmt_group_handlers_fixed);
#endif
	mgmt_register_group(&os_mgmt_group);
}

MCUMGR_HANDLER_DEFINE(os_mgmt, os_mgmt_register_group);
